body.value:
{%- comment -%}
  Honigmama-Reihe: drei Bände + zwei Pakete. Aufruf: render 'hm-series', current: product.handle, mode: 'full' | 'upsell'
  Unveröffentlichte Produkte erscheinen als „Bald verfügbar“.
{%- endcomment -%}
{%- assign mode = mode | default: 'full' -%}
{%- capture rows -%}
honigmama-band-1|Band 1|Was darf ich essen?|Schwangerschaft · 70 Rezepte · 3 Wochenpläne|bq-cover-honigmama.jpg
honigmama-band-2|Band 2|Vorkochen fürs Wochenbett|Wochenbett · 40 Gerichte zum Einfrieren · 6-Wochen-Plan|hm-b2_1.jpg
honigmama-band-3|Band 3|Kraft-Küche fürs erste Jahr|Erstes Jahr · 50 schnelle Rezepte · 4 Wochenpläne|hm-b3_1.jpg
{%- endcapture -%}
{%- capture packs -%}
honigmama-paket-band-1-2|Paket|Schwangerschaft + Wochenbett|Band 1 + 2 · 110 Rezepte|hm-bundle12.jpg
honigmama-komplett|Komplett|Die ganze Reihe|Band 1 + 2 + 3 · 160 Rezepte · bestes Angebot|hm-bundle123.jpg
{%- endcapture -%}
<style>
.hm-series{padding:3.5rem 0;background:#fbf4e7}.hm-series--upsell{background:#fff7e6;border-top:1px solid #ead8b4;border-bottom:1px solid #ead8b4}
.hm-series h2{margin:.2rem 0 .4rem}.hm-series__lead{max-width:40rem;margin:0 0 1.6rem;opacity:.85}
.hm-grid{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(210px,1fr))}
.hm-card{background:#fff;border:1px solid #ead8b4;border-radius:16px;padding:14px;display:flex;flex-direction:column;gap:8px;position:relative}
.hm-card img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:10px;display:block;background:#f3e7d2}
.hm-card__band{font:700 12px/1 var(--font-body--family,Arial,sans-serif);letter-spacing:.12em;text-transform:uppercase;color:#a97016}
.hm-card h3{margin:0;font-size:1.15rem;line-height:1.2}.hm-card p{margin:0;font-size:.9rem;opacity:.85}
.hm-card__price{font-weight:700;font-size:1.05rem}.hm-card__price s{opacity:.55;font-weight:500;margin-left:6px}
.hm-card .bq-button,.hm-card button{margin-top:auto;width:100%}
.hm-card--best{border:2px solid #b4532f}.hm-card--best:before{content:"Bestes Angebot";position:absolute;top:-11px;left:14px;background:#b4532f;color:#fff;font:700 12px/1 var(--font-body--family,Arial,sans-serif);padding:6px 10px;border-radius:99px}
.hm-soon{margin-top:auto;text-align:center;padding:12px;border-radius:99px;background:#f3e7d2;font-weight:600;font-size:.9rem}
.hm-packs{margin-top:22px}
</style>
<section class="hm-series{% if mode == 'upsell' %} hm-series--upsell{% endif %}" id="hm-reihe"><div class="bq-wrap">
{%- if mode == 'upsell' -%}
<p class="bq-eyebrow">Passt dazu</p><h2>Mach die Reihe komplett – und spar mit dem Paket.</h2>
<p class="hm-series__lead">Honigmama begleitet dich von der Schwangerschaft über das Wochenbett bis ins erste Jahr. Im Paket bekommst du alle Bände günstiger.</p>
{%- else -%}
<p class="bq-eyebrow">Die Honigmama-Reihe</p><h2>Ein Kochbuch für jede Phase.</h2>
<p class="hm-series__lead">Schwangerschaft, Wochenbett, erstes Jahr: Jede Phase hat ihre eigene Essens-Frage. Für jede gibt es einen Band mit fertigen Plänen und Einkaufslisten.</p>
{%- endif -%}
{%- for section_rows in (1..2) -%}
{%- if section_rows == 1 -%}{%- assign list = rows | strip | split: '
' -%}{%- if mode == 'upsell' -%}{%- continue -%}{%- endif -%}{%- else -%}{%- assign list = packs | strip | split: '
' -%}{%- endif -%}
<div class="hm-grid{% if section_rows == 2 and mode != 'upsell' %} hm-packs{% endif %}">
{%- for row in list -%}{%- assign c = row | strip | split: '|' -%}{%- assign h = c[0] -%}
{%- if h == current -%}{%- continue -%}{%- endif -%}
{%- assign p = all_products[h] -%}
<article class="hm-card{% if h == 'honigmama-komplett' %} hm-card--best{% endif %}">
{%- if p != blank and p.featured_image -%}{{ p.featured_image | image_url: width: 500 | image_tag: loading: 'lazy', alt: c[2] }}{%- elsif images[c[4]] != blank -%}{{ images[c[4]] | image_url: width: 500 | image_tag: loading: 'lazy', alt: c[2] }}{%- endif -%}
<span class="hm-card__band">{{ c[1] }}</span><h3>{{ c[2] }}</h3><p>{{ c[3] }}</p>
{%- if p != blank and p.available -%}
{%- assign v = p.selected_or_first_available_variant -%}
<p class="hm-card__price">{{ v.price | money }}{% if v.compare_at_price > v.price %}<s>{{ v.compare_at_price | money }}</s>{% endif %}</p>
<form method="post" action="/cart/add"><input type="hidden" name="id" value="{{ v.id }}"><input type="hidden" name="return_to" value="/checkout"><button class="bq-button" type="submit">{% if mode == 'upsell' %}Dazu kaufen{% else %}Jetzt kaufen{% endif %}</button></form>
<a class="bq-link" href="{{ p.url }}" style="font-size:.85rem;text-align:center">Mehr erfahren</a>
{%- else -%}<div class="hm-soon">Bald verfügbar</div>{%- endif -%}
</article>
{%- endfor -%}
</div>
{%- endfor -%}
</div></section>

{%- case product.handle -%}
{%- when 'honigmama-band-2' -%}{%- assign hm_n = 40 -%}{%- assign hm_eyebrow = 'Honigmama · Band 2 · Das Kochbuch für das Wochenbett' -%}{%- assign hm_facts = '40 Gerichte zum Einfrieren|2 Kochtage + Einkaufslisten|6-Wochen-Plan' -%}{%- assign hm_final = 'Sechs Wochen warmes Essen – ohne nach der Geburt zu kochen.' -%}{%- assign hm_final2 = '40 Gerichte, 2 Kochtage und ein 6-Wochen-Plan' -%}{%- assign hm_preview = 'Echte Seiten: Rezepte mit Einfrier- und Aufwärm-Hinweisen, Kochtag-Ablauf und 6-Wochen-Plan. Antippen zum Vergrößern.' -%}
{%- when 'honigmama-band-3' -%}{%- assign hm_n = 50 -%}{%- assign hm_eyebrow = 'Honigmama · Band 3 · Das Kochbuch fürs erste Jahr' -%}{%- assign hm_facts = '50 Rezepte in 5–25 Min.|4 Wochenpläne + Einkaufslisten|Fürs Baby abzweigen' -%}{%- assign hm_final = 'Wieder richtig essen statt Reste vom Kinderteller.' -%}{%- assign hm_final2 = '50 schnelle Rezepte und 4 Wochenpläne' -%}{%- assign hm_preview = 'Echte Seiten: schnelle Rezepte mit Tipps, Baby-Hinweisen und fertigen Wochenplänen mit Einkaufsliste. Antippen zum Vergrößern.' -%}
{%- when 'honigmama-paket-band-1-2' -%}{%- assign hm_n = 110 -%}{%- assign hm_eyebrow = 'Honigmama · Paket Band 1 + 2' -%}{%- assign hm_facts = '110 Rezepte|Schwangerschaft + Wochenbett|2 PDFs sofort' -%}{%- assign hm_final = 'Gut versorgt – vor und nach der Geburt.' -%}{%- assign hm_final2 = 'Band 1 + Band 2 im Paket' -%}{%- assign hm_preview = 'Echte Seiten aus beiden Bänden. Antippen zum Vergrößern.' -%}
{%- when 'honigmama-komplett' -%}{%- assign hm_n = 160 -%}{%- assign hm_eyebrow = 'Honigmama · Die komplette Reihe' -%}{%- assign hm_facts = '160 Rezepte|13 fertige Pläne|3 PDFs sofort' -%}{%- assign hm_final = 'Von der Schwangerschaft bis ins erste Jahr: alles geplant.' -%}{%- assign hm_final2 = 'Alle drei Bände im Paket' -%}{%- assign hm_preview = 'Echte Seiten aus allen drei Bänden. Antippen zum Vergrößern.' -%}
{%- else -%}{%- assign hm_n = 70 -%}{%- assign hm_eyebrow = 'Honigmama · Das Kochbuch für die Schwangerschaft' -%}{%- assign hm_facts = '70 Rezepte|3 Wochenpläne + Einkaufslisten|Lebensmittelhinweise' -%}{%- assign hm_final = 'Nicht mehr googeln, was du essen darfst.' -%}{%- assign hm_final2 = '70 Rezepte, 3 Wochenpläne und Lebensmittelhinweise' -%}{%- assign hm_preview = 'Echte Seiten: Rezepte mit Foto und Schritt-für-Schritt-Anleitung, Lebensmittelhinweise zum Nachschlagen und fertige Wochenpläne mit Einkaufsliste. Antippen zum Vergrößern.' -%}
{%- endcase -%}
{% assign item = product %}{% assign selected = item.selected_or_first_available_variant %}{% assign main_id = 'bq-purchase-' | append: section.id %}{% assign end_id = main_id | append: '-end' %}{% assign mid_id = main_id | append: '-mid' %}{% assign sticky_id = main_id | append: '-sticky' %}{% assign bee_id = main_id | append: '-bee' %}{% assign value_id = main_id | append: '-value' %}{% assign angle_id = main_id | append: '-angle' %}{% assign gallery_id = 'bq-gallery-' | append: section.id %}{% assign media_id = 'bq-product-media-' | append: section.id %}{% assign per_recipe = selected.price | divided_by: hm_n %}
<style>.bq-product-hero .bq-product-copy .bq-eyebrow{margin:0 0 6px}.bq-hero-facts{list-style:none;padding:0;margin:8px 0 14px;display:flex;flex-wrap:wrap;gap:6px}.bq-hero-facts li{background:#fff7e6;border:1px solid #ead8b4;border-radius:99px;padding:4px 11px;font:500 14px/1.4 var(--font-body--family,Arial,sans-serif);color:#4a3a2c}.bq-per-recipe{display:inline-flex;align-items:center;gap:6px;margin:2px 0 14px;padding:4px 11px;border-radius:99px;background:#efd39b;color:#5a3a10;font:600 14px/1.4 var(--font-body--family,Arial,sans-serif)}.bq-trustline{display:flex;flex-wrap:wrap;gap:4px 14px;margin:12px 0 10px;font:500 13.5px/1.4 var(--font-body--family,Arial,sans-serif);color:#5b4c3f}.bq-trustline span{display:inline-flex;align-items:center;gap:5px}.bq-trustline svg{width:15px;height:15px;color:#845119}.bq-mid-cta{max-width:28rem;margin:2rem auto 0;text-align:center}.bq-mid-cta p{margin:.6rem 0 0;font-size:.9rem;opacity:.8}.bq-about__grid{display:grid;gap:1.5rem;align-items:center}@media (min-width:800px){.bq-about__grid{grid-template-columns:220px 1fr}.bq-product-hero .bq-product-grid{grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr)!important;align-items:start}}.bq-about__img img{width:100%;max-width:220px;height:auto;border-radius:12px;display:block}.bq-testers__note{font-size:.9rem;opacity:.85;margin-top:1rem}.bq-product-hero .bq-pdp-media--refresh .bq-pdp-media__image>img{width:100%!important;height:auto!important;max-height:none!important;object-fit:contain}@media (max-width:799px){.bq-product-hero .bq-pdp-media--refresh .bq-pdp-media__image>img{max-height:66svh!important;width:auto!important;max-width:100%!important;margin-inline:auto;display:block}.bq-product-hero .bq-product-copy h1{margin-bottom:4px}}.bq-preview-section .bq-slide figcaption{font-weight:600;color:#4a3a2c}</style>
<section class="bq-product-hero" id="bq-kaufen">{% render 'bq-drip' %}<div class="bq-wrap bq-product-grid">
{% render 'bq-product-media', item: item, cover: section.settings.cover, media_id: media_id %}
<div class="bq-product-copy">{% render 'bq-reviews', item: item, mode: 'summary' %}<p class="bq-eyebrow">{{ hm_eyebrow }}</p><h1>{{ item.title | escape }}</h1>
<ul class="bq-hero-facts">{% assign hf = hm_facts | split: "|" %}{% for f in hf %}<li>{{ f }}</li>{% endfor %}</ul>
{% render 'bq-price', item: item %}{% if selected.price > 0 %}<p class="bq-per-recipe">= nur {{ per_recipe | money }} pro Rezept</p>{% endif %}
<div class="bq-product-primary" data-bq-cta>{% render 'bq-purchase', item: item, form_id: main_id, compact: true %}</div>
<p class="bq-trustline"><span>{% render 'bq-icon', name: 'lock' %}Sicherer Checkout</span><span>{% render 'bq-icon', name: 'check' %}Sofort-Download</span><span>{% render 'bq-icon', name: 'check' %}Kein Abo</span><span>{% render 'bq-icon', name: 'check' %}Ideal als Geschenk</span></p>
{% render 'bq-payments' %}</div></div></section>
{% render 'bq-press', item: item %}
{% if hm_n == 70 %}{% render 'bq-dishes' %}
{% render 'bq-bee-promise', item: item, form_id: bee_id %}{% endif %}
<section class="bq-section bq-preview-section" id="vorschau"><div class="bq-wrap"><div class="bq-section-head"><div><p class="bq-eyebrow">Ein Blick ins Buch</p><h2>So sieht dein Buch von innen aus.</h2></div><p>{{ hm_preview }}</p></div>{% render 'bq-book-carousel', item: item, gallery_id: gallery_id %}<div class="bq-mid-cta" data-bq-cta>{% render 'bq-purchase', item: item, form_id: mid_id, compact: true %}<p>{{ selected.price | money }} einmalig · PDF · kein Abo</p></div></div></section>
{% if hm_n == 70 %}{% render 'bq-value', item: item, form_id: value_id %}
{% render 'bq-angles', item: item, form_id: angle_id %}{% endif %}
{% render 'hm-series', current: item.handle, mode: 'upsell' %}
{% if section.settings.about_text != blank %}<section class="bq-section bq-section--soft bq-about" id="bq-ueber"><div class="bq-wrap bq-about__grid">{% if section.settings.about_image != blank %}<div class="bq-about__img">{{ section.settings.about_image | image_url: width: 600 | image_tag: loading: 'lazy', alt: section.settings.about_name }}</div>{% endif %}<div><p class="bq-eyebrow">Wer hinter Honigmama steckt</p><h2>{{ section.settings.about_title | default: 'Warum es dieses Buch gibt' | escape }}</h2>{% if section.settings.about_name != blank %}<p><strong>{{ section.settings.about_name | escape }}</strong></p>{% endif %}{{ section.settings.about_text }}</div></div></section>{% endif %}
{% assign tester_count = 0 %}{% for block in section.blocks %}{% if block.type == 'tester' %}{% assign tester_count = tester_count | plus: 1 %}{% endif %}{% endfor %}
{% if tester_count > 0 %}<section class="bq-section bq-testers" id="bq-testleserinnen"><div class="bq-wrap"><p class="bq-eyebrow">Vorab gelesen</p><h2>Stimmen von Testleserinnen</h2><div class="bq-review-list">{% for block in section.blocks %}{% if block.type == 'tester' %}<article class="bq-review" {{ block.shopify_attributes }}><p class="bq-review__author">{{ block.settings.name | escape }}</p><p>{{ block.settings.text | escape | newline_to_br }}</p></article>{% endif %}{% endfor %}</div><p class="bq-testers__note">Diese Personen haben das E-Book vorab kostenlos erhalten und gelesen. Es handelt sich nicht um verifizierte Käufe. Die Aussagen sind unverändert und mit Zustimmung veröffentlicht.</p></div></section>{% endif %}
<section class="bq-section bq-section--soft" id="bq-fragen"><div class="bq-wrap bq-faq-layout"><div><p class="bq-eyebrow">{{ 'bq.product.faq_kicker' | t }}</p><h2>{{ 'bq.product.faq_title' | t }}</h2><a class="bq-link" href="mailto:{{ shop.email }}">{{ 'bq.product.support' | t }}{% render 'bq-icon', name: 'arrow' %}</a></div><div class="bq-faq">{% for block in section.blocks %}{% if block.type == 'faq' %}<details {{ block.shopify_attributes }}><summary>{{ block.settings.question }}<span aria-hidden="true">+</span></summary><div>{{ block.settings.answer }}</div></details>{% endif %}{% endfor %}<details><summary>Kann ich das Buch verschenken?<span aria-hidden="true">+</span></summary><div><p>Ja. Nach dem Kauf bekommst du die PDF sofort per E-Mail und als Download. Du kannst sie der werdenden Mama weiterleiten oder ausdrucken und überreichen.</p></div></details>{% if hm_n == 70 %}<details><summary>Worauf stützen sich die Lebensmittelhinweise?<span aria-hidden="true">+</span></summary><div><p>Auf die Empfehlungen von Netzwerk Gesund ins Leben und dem Bundesinstitut für Risikobewertung (BfR). <a href="/pages/ernaehrung-schwangerschaft-quellen">Alle Quellen ansehen</a></p></div></details>{% endif %}<details><summary>{{ 'bq.product.transparency_title' | t }}<span aria-hidden="true">+</span></summary><div><p>Die Vorschau zeigt echte Buchseiten. Die Bilder der Gerichte und Personen wurden mit KI erstellt; sie sind keine Fotos nachgekochter Rezepte.</p><p>{{ 'bq.product.advice' | t }}</p></div></details></div></div></section>
<section class="bq-section"><div class="bq-wrap bq-final-purchase"><h2>{{ hm_final }}</h2><p>{{ hm_final2 }} – für {{ per_recipe | money }} pro Rezept.</p><div data-bq-cta>{% render 'bq-purchase', item: item, form_id: end_id %}</div></div></section>
{% render 'bq-reviews', item: item %}
<aside class="bq-sticky" data-bq-sticky data-bq-sticky-entry hidden aria-label="{{ 'bq.product.sticky' | t }}"><div class="bq-sticky__inner"><div class="bq-sticky__product"><div><strong>{{ item.title | escape }}</strong><span>{{ selected.price | money }} · {{ hm_n }} Rezepte · PDF</span></div></div>{% render 'bq-purchase', item: item, form_id: sticky_id, compact: true, sticky: true %}<p class="bq-sticky__trust">{% render 'bq-icon', name: 'lock' %}{{ 'bq.trust.checkout' | t }} <span>· {{ 'bq.trust.no_subscription' | t }}</span></p></div></aside>
{% render 'bq-buy-dialog' %}
{% render 'bq-image-dialog', item: item %}
<script type="application/ld+json">{"@context":"https://schema.org","@type":"Book","name":{{ item.title | json }},"bookFormat":"https://schema.org/EBook","inLanguage":"de","url":{{ canonical_url | json }}{% if item.featured_image %},"image":{{ item.featured_image | image_url: width: 1200 | prepend: 'https:' | json }}{% endif %}{% if selected.available and selected.price > 0 %},"offers":{"@type":"Offer","price":{{ selected.price | divided_by: 100.0 | json }},"priceCurrency":{{ cart.currency.iso_code | json }},"availability":"https://schema.org/InStock","url":{{ canonical_url | json }}}{% endif %}}</script>
{% schema %}
{"name":"BeeQueen: Produktseite","settings":[{"type":"image_picker","id":"cover","label":"Echtes Buchcover"},{"type":"header","content":"Über mich (erscheint nur, wenn Text ausgefüllt)"},{"type":"image_picker","id":"about_image","label":"Foto von dir"},{"type":"text","id":"about_name","label":"Dein Name"},{"type":"text","id":"about_title","label":"Überschrift","default":"Warum es dieses Buch gibt"},{"type":"richtext","id":"about_text","label":"Text über dich (nur wahre Angaben)"}],"blocks":[{"type":"faq","name":"Frage","settings":[{"type":"text","id":"question","label":"Frage"},{"type":"richtext","id":"answer","label":"Antwort"}]},{"type":"tester","name":"Testleserin","settings":[{"type":"text","id":"name","label":"Name (mit Zustimmung)"},{"type":"textarea","id":"text","label":"Unveränderte Aussage (kein „gekauft“, wenn geschenkt)"}]}]}
{% endschema %}

{% assign item = section.settings.product %}
{% assign selected = item.selected_or_first_available_variant %}{% assign hero_id = 'bq-home-hero-' | append: section.id %}{% assign offer_id = hero_id | append: '-offer' %}{% assign end_id = hero_id | append: '-end' %}{% assign sticky_id = hero_id | append: '-sticky' %}{% assign bee_id = hero_id | append: '-bee' %}{% assign value_id = hero_id | append: '-value' %}{% assign angle_id = hero_id | append: '-angle' %}{% assign gallery_id = 'bq-gallery-' | append: section.id %}{% assign per_recipe = selected.price | divided_by: 70 %}
<section class="bq-hero">
{% render 'bq-drip' %}
<div class="bq-wrap bq-hero__grid">
<div class="bq-hero__heading"><p class="bq-eyebrow">{{ 'bq.home.eyebrow' | t }}</p><h1>{{ 'bq.home.title1' | t }}<br><em>{{ 'bq.home.title2' | t }}</em></h1></div>
<figure class="bq-hero__art"><span class="bq-hero__halo" aria-hidden="true"></span>
{% if section.settings.mascot != blank %}{{ section.settings.mascot | image_url: width: 1000 | image_tag: class: 'bq-hero__queen', loading: 'eager', fetchpriority: 'high', widths: '360,600,800,1000', sizes: '(min-width: 800px) 430px, 180px', alt: section.settings.mascot_alt }}{% endif %}
{% if section.settings.cover != blank %}{{ section.settings.cover | image_url: width: 600 | image_tag: class: 'bq-hero__cover', loading: 'eager', widths: '200,400,600', sizes: '(min-width: 800px) 170px, 94px', alt: item.title }}{% endif %}
<span class="bq-hero__stamp" aria-hidden="true">{% render 'bq-icon', name: 'book' %}</span>
</figure>
<div class="bq-hero__copy"><ul class="bq-hero-points">{% for i in (1..3) %}{% assign point_key = 'bq.home.hero_point' | append: i %}<li>{% render 'bq-icon', name: 'check' %}<span>{{ point_key | t }}</span></li>{% endfor %}</ul><p class="bq-hero__price">{{ selected.price | money }} <span>· einmalig · nur {{ per_recipe | money }} pro Rezept</span></p><div data-bq-cta>{% render 'bq-purchase', item: item, form_id: hero_id, compact: true %}</div><a class="bq-peek-link" href="#bq-gerichte">Diese Gerichte kochst du{% render 'bq-icon', name: 'arrow' %}</a></div>
</div>
</section>
{% render 'bq-press', item: item %}
{% render 'hm-series', current: '', mode: 'full' %}
{% render 'bq-dishes' %}
{% render 'bq-bee-promise', item: item, form_id: bee_id %}
<section class="bq-section bq-preview-section" id="vorschau"><div class="bq-wrap"><div class="bq-section-head"><div><p class="bq-eyebrow">Ein Blick ins Buch</p><h2>So sieht dein Buch von innen aus.</h2></div><a class="bq-link" href="{{ item.url }}">Zum Kochbuch{% render 'bq-icon', name: 'arrow' %}</a></div>{% render 'bq-book-carousel', item: item, gallery_id: gallery_id %}</div></section>
{% render 'bq-value', item: item, form_id: value_id %}
{% render 'bq-angles', item: item, form_id: angle_id %}
{% render 'bq-reviews', item: item %}
<section class="bq-section"><div class="bq-wrap bq-end"><h2>{{ 'bq.home.end_title' | t }}</h2><p>{{ 'bq.home.end_text' | t }}</p><div data-bq-cta>{% render 'bq-purchase', item: item, form_id: end_id %}</div>
<div class="bq-probe" id="bq-probieren"><div><h3>{{ 'bq.home.probe_title' | t }}</h3><p>{{ 'bq.home.probe_text' | t }}</p></div>
{% form 'customer', id: 'bq-probe-form', class: 'bq-email-form' %}<input type="hidden" name="contact[tags]" value="newsletter, probierheft">
{% if form.posted_successfully? %}<p role="status">{{ 'bq.home.probe_success' | t }}</p>{% else %}{% if form.errors %}<div class="bq-error" role="alert">{{ form.errors | default_errors }}</div>{% endif %}<label for="bq-probe-email">{{ 'bq.home.email' | t }}</label><input id="bq-probe-email" type="email" name="contact[email]" value="{{ form.email | escape }}" autocomplete="email" required placeholder="name@beispiel.de"><label class="bq-consent"><input type="checkbox" name="contact[accepts_marketing]" value="true" required><span>{{ 'bq.home.probe_consent' | t }}{% if pages['datenschutz'] != blank %} <a href="{{ pages['datenschutz'].url }}">{{ 'bq.nav.privacy' | t }}</a>{% elsif shop.privacy_policy.body != blank %} <a href="{{ shop.privacy_policy.url }}">{{ 'bq.nav.privacy' | t }}</a>{% endif %}</span></label><button class="bq-button bq-button--outline" type="submit">{{ 'bq.home.probe_cta' | t }}</button>{% endif %}
{% endform %}</div></div></section>
<aside class="bq-sticky" data-bq-sticky hidden aria-label="{{ 'bq.product.sticky' | t }}"><div class="bq-sticky__inner"><div class="bq-sticky__product">{% if item.featured_image != blank %}{{ item.featured_image | image_url: width: 120 | image_tag: loading: 'lazy', alt: '' }}{% endif %}<div><strong>{{ item.title | escape }}</strong><span>{% if selected.price > 0 %}{{ selected.price | money }} · {% endif %}70 Rezepte · PDF</span></div></div>{% render 'bq-purchase', item: item, form_id: sticky_id, compact: true, sticky: true %}<p class="bq-sticky__trust">{% render 'bq-icon', name: 'lock' %}{{ 'bq.trust.checkout' | t }} <span>· {{ 'bq.trust.pdf' | t }}</span></p></div></aside>
{% render 'bq-buy-dialog' %}
